def breakSum(n):
    if n < 4:
        return n

    # Memoization dictionary
    memo = {}

    def helper(num):
        if num in memo:
            return memo[num]

        # Base case: if number is less than 4, we don't split it further
        if num < 4:
            memo[num] = num
            return num

        # Split into three parts and recursively calculate maximum sum
        part1 = helper(num // 2)
        part2 = helper(num // 3)
        part3 = helper(num // 4)

        # Return the maximum of splitting or not splitting
        memo[num] = max(num, part1 + part2 + part3)
        return memo[num]

    return helper(n)

