import sys
from math import sqrt

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px, py = find(parent, x), find(parent, y)
    if px != py:
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True
    return False

def distance_squared(p1, p2):
    return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    points = []
    idx = 1
    for _ in range(N):
        x = int(data[idx])
        y = int(data[idx+1])
        points.append((x, y))
        idx += 2

    edges = []
    for i in range(N):
        for j in range(i + 1, N):
            dist_sq = distance_squared(points[i], points[j])
            edges.append((dist_sq, i, j))

    edges.sort()

    parent = list(range(N))
    rank = [0] * N
    total_cost = 0
    edges_used = 0

    for cost, u, v in edges:
        if union(parent, rank, u, v):
            total_cost += cost
            edges_used += 1
            if edges_used == N - 1:
                break

    print(total_cost)

if __name__ == "__main__":
    main()
